### 1) Create `.pi/extensions/modes.ts`

```ts
import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";

export default function modes(pi: ExtensionAPI) {
  let mode: "plan" | "build" = "build";

  const applyMode = () => {
    pi.setActiveTools(
      mode === "plan"
        ? ["read", "bash", "grep", "find", "ls"] // no edit/write
        : ["read", "bash", "edit", "write"]
    );
  };

  const setMode = (next: "plan" | "build", ctx?: any) => {
    mode = next;
    applyMode();
    ctx?.ui.notify(`Mode: ${mode}`, "info");
  };

  pi.registerFlag("plan", {
    description: "Start in plan mode",
    type: "boolean",
    default: false,
  });

  pi.registerCommand("plan", {
    description: "Switch to plan mode",
    handler: async (_args, ctx) => setMode("plan", ctx),
  });

  pi.registerCommand("build", {
    description: "Switch to build mode",
    handler: async (_args, ctx) => setMode("build", ctx),
  });

  pi.on("before_agent_start", async (event) => {
    const extra =
      mode === "plan"
        ? `PLAN MODE:\n- Analyze only\n- Do not modify files\n- Return numbered plan`
        : `BUILD MODE:\n- Implement approved plan\n- Make minimal edits\n- Validate changes`;
    return { systemPrompt: `${event.systemPrompt}\n\n${extra}` };
  });

  pi.on("session_start", async (_event, ctx) => {
    if (pi.getFlag("plan") === true) mode = "plan";
    applyMode();
    ctx.ui.notify(`Mode: ${mode}`, "info");
  });
}
```

---

### 2) Reload and use

- Put file in `.pi/extensions/modes.ts`
- Run `/reload`
- Use:
  - `/plan`
  - `/build`
  - or start with `pi --plan`

---

If you want, I can also give you a stricter version that blocks destructive `bash` commands in plan mode (like the full `examples/extensions/plan-mode/` sample).

