```ts
import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";

type Level = "off" | "lite" | "full" | "ultra";

export default function caveman(pi: ExtensionAPI) {
  let level: Level = "off";

  pi.registerFlag("caveman", {
    description: "Start in caveman terse-output mode",
    type: "boolean",
    default: false,
  });

  function instructions() {
    if (level === "off") return "";

    if (level === "lite") {
      return `
CAVEMAN LITE MODE:
- Be concise.
- Drop filler, throat-clearing, apologies.
- Keep normal grammar.
- Preserve all technical accuracy.
- Prefer bullets, short sentences, direct answers.
`;
    }

    if (level === "full") {
      return `
CAVEMAN FULL MODE:
- Use few words.
- No filler.
- Fragment okay.
- Technical accuracy stay full.
- Answer first, explain only needed.
- Prefer code/diffs over prose.
- Say cause, fix, validate.
`;
    }

    return `
CAVEMAN ULTRA MODE:
- Maximum compression.
- Telegraphic.
- No greetings, no recap, no hedging.
- Keep exact commands, paths, identifiers, code unchanged.
- Output only essential facts/actions.
`;
  }

  function setStatus(ctx: any) {
    if (level === "off") ctx.ui.setStatus("caveman", undefined);
    else ctx.ui.setStatus("caveman", ctx.ui.theme.fg("accent", `🪨 ${level}`));
  }

  pi.registerCommand("caveman", {
    description: "Toggle caveman terse-output mode: off|lite|full|ultra",
    handler: async (args, ctx) => {
      const arg = args.trim() as Level;

      if (arg === "off" || arg === "lite" || arg === "full" || arg === "ultra") {
        level = arg;
      } else {
        level = level === "off" ? "full" : "off";
      }

      setStatus(ctx);
      ctx.ui.notify(`Caveman mode: ${level}`, "info");
    },
  });

  pi.registerCommand("caveman-help", {
    description: "Show caveman commands",
    handler: async (_args, ctx) => {
      ctx.ui.notify(
        `/caveman          toggle full/off
/caveman lite     concise, normal grammar
/caveman full     terse fragments
/caveman ultra    maximum compression
/caveman off      disable`,
        "info"
      );
    },
  });

  pi.on("before_agent_start", async (event) => {
    const extra = instructions();
    if (!extra) return;

    return {
      systemPrompt: `${event.systemPrompt}\n\n${extra}`,
    };
  });

  pi.on("session_start", async (_event, ctx) => {
    if (pi.getFlag("caveman") === true) level = "full";
    setStatus(ctx);
  });
}
```

## Usage

```bash
pi --caveman
```

Inside Pi:

```txt
